<div class="section-title"><div><h1>My claims</h1><p class="muted">Track administrator decisions.</p></div></div>
<?php if (!$claims): ?><div class="card empty">You have not submitted any claims.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Lost report</th><th>Found item</th><th>Status</th><th>Submitted</th><th>Administrator note</th></tr></thead><tbody><?php foreach ($claims as $claim): ?><tr><td><a href="<?= h(url('item.php?id=' . $claim['lost_item_id'])) ?>"><?= h($claim['lost_title']) ?></a></td><td><a href="<?= h(url('item.php?id=' . $claim['found_item_id'])) ?>"><?= h($claim['found_title']) ?></a></td><td><?= status_badge($claim['status']) ?></td><td><?= h($claim['created_at']) ?></td><td><?= h($claim['admin_notes'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
